def G(t):
    R=[("Create with Gemini","Кріейт віз Джеміні"),("Upload a skill","Аплоуд е скіл"),("Create skill","Кріейт скіл"),("Add custom connector","Ед кастом конектор"),("Allow always","Еллау олвейз"),("Google Drive","Гугл Драйв"),("Keep Activity","Кіп Ектівіті"),("SKILL.md","скіл точка ем-ді"),("Create","Кріейт"),(" Add"," Ед"),("ChatGPT","Чат Джі-Пі-Ті"),("Customize","Кастомайз"),("Skills","Скілз"),("Connectors","Конектори"),("Settings","Сеттінгз"),("Capabilities","Кейпабіліті"),
       ("Gemini","Джеміні"),("Google","Гугл"),("Claude","Клод"),("Anthropic","Ентропік"),("OpenAI","Оупен Ей-Ай"),("MCP","Ем-Сі-Пі"),("USB-C","ю-ес-бі тайп-сі"),
       ("Excel","Ексель"),("Word","Ворд"),("PowerPoint","Пауерпоінт"),("PDF","Пі-Ді-Еф"),("ZIP","зіп"),("SKILL.md","скіл точка ем-ді"),("Gmail","Джимейл"),("Notion","Ноушн"),
       ("Google Drive","Гугл Драйв"),("Drive","Драйв"),("Keep Activity","Кіп Ектівіті"),("Gems","Джеми"),("Upload","Аплоуд"),("Create with Gemini","Кріейт віз Джеміні"),
       ("Allow always","Еллау олвейз"),("Pro","Про"),("Plus","Плюс"),("Free","Фрі"),("Go","Гоу"),("Business","Бізнес"),("Max","Макс"),("Add custom connector","Ед кастом конектор")]
    for a,b in R: t=t.replace(a,b)
    t=re.sub(r"ШІ-(\w+)", r"\1 штучного інтелекту", t)
    for a,b in [("від ШІ","від штучного інтелекту"),("з ШІ","зі штучним інтелектом"),("ШІ не","штучний інтелект не"),("у ШІ","у штучний інтелект")]: t=t.replace(a,b)
    return t.replace("ШІ","штучний інтелект")

